from datetime import datetime

def validate_gdpr_consent(record):
    errors = {}

    # Check 'consented' is a boolean set to True
    if not record.get('consented') or not isinstance(record['consented'], bool):
        errors['consented'] = "Consented must be a boolean set to True."

    # Check 'purpose' is a non-empty string
    if not record.get('purpose') or not isinstance(record['purpose'], str) or not record['purpose']:
        errors['purpose'] = "Purpose must be a non-empty string."

    # Check 'timestamp' is a non-empty string in UTC ISO-8601 format
    if not record.get('timestamp') or not isinstance(record['timestamp'], str) or not record['timestamp']:
        errors['timestamp'] = "Timestamp must be a non-empty string in UTC ISO-8601 format."
    else:
        try:
            datetime.strptime(record['timestamp'], "%Y-%m-%dT%H:%M:%S%z")
        except ValueError:
            errors['timestamp'] = "Invalid timestamp format. Must be in UTC ISO-8601 format."

    # Check 'withdrawal_url' is a non-empty string
    if not record.get('withdrawal_url') or not isinstance(record['withdrawal_url'], str) or not record['withdrawal_url']:
        errors['withdrawal_url'] = "Withdrawal URL must be a non-empty string."

    return errors
```

### Explanation:
1. **Consented Check**: Ensures the `consented` field is a boolean set to `True`.
2. **Purpose Check**: Validates that the `purpose` is a non-empty string.
3. **Timestamp Check**: Validates that the `timestamp` is a non-empty string in the format `YYYY-MM-DDTHH:MM:SSZ` (UTC). Uses `datetime.strptime` to ensure correct format.
4. **Withdrawal URL Check**: Ensures the `withdrawal_url` is a non-empty string.

The function returns a dictionary mapping failing fields to descriptive error messages.
